        assertEquals(HttpStatus.OK, resp.getStatusCode());
        NotificationEvent[] body = resp.getBody();
        assertTrue(body != null && body.length >= 1);
        boolean found = Arrays.stream(body).anyMatch(e -> "11111111-1111-1111-1111-111111111111".equals(e.getId().toString()));
        assertTrue(found, "Expected seeded event for client-a to be present");
    }

    @Test
    void shouldNotAllowAccessToOtherClientsEvents() {
        // client-a should not be able to fetch client-b event
        ResponseEntity<String> resp = restTemplate.withBasicAuth("client-a", "password")
                .getForEntity("http://localhost:" + port + "/notification_events/22222222-2222-2222-2222-222222222222", String.class);

        assertEquals(HttpStatus.NOT_FOUND, resp.getStatusCode());
    }
}
